"""One browser audio engine shared by the Media page and Music Player slots."""
MUSIC = r'''
<style>
.music-controls {display:flex;gap:8px;align-items:center;flex-wrap:wrap}.music-controls select {max-width:100%;min-width:140px}.music-track {display:grid;grid-template-columns:1fr 1fr 2fr auto;gap:8px;margin:8px 0}.music-track input,.music-track select {min-width:0;width:100%;box-sizing:border-box}.music-dock {position:fixed;bottom:12px;right:16px;z-index:1000;max-width:calc(100vw - 32px);padding:10px 14px;border:1px solid var(--border);border-radius:14px;background:var(--panel);color:var(--text);box-shadow:0 8px 30px #0005}.music-dock audio {width:min(300px,75vw);height:36px;display:block}.music-dock p {font-size:12px;margin:4px 0}.music-dock[hidden] {display:none!important}@media(max-width:700px){.music-track {grid-template-columns:1fr auto}.music-track input:first-child,.music-track select {grid-column:1/-1}}
</style>
<script>
(()=>{
'use strict';
const el=(tag,text='')=>{const node=document.createElement(tag);node.textContent=text;return node;},bridge=()=>window.dashboardModuleState;
const dock=el('section');dock.className='music-dock';dock.setAttribute('aria-label','Now playing');dock.hidden=true;
const title=el('p'),audio=document.createElement('audio'),note=el('p'),stop=el('button','Stop music');audio.id='persistent-music-audio';audio.controls=true;audio.preload='none';stop.type='button';dock.append(title,audio,note,stop);document.body.append(dock);
let tracks=[],index=-1,blobURL=null,loading=null,ticket=0,owner='',library={uploads:[],server_files:[]};const views=new Set();
function clear(){ticket++;loading?.abort();loading=null;audio.pause();audio.removeAttribute('src');audio.load();if(blobURL)URL.revokeObjectURL(blobURL);blobURL=null;dock.hidden=true;}
function message(value){note.textContent=value;update();}
function update(){for(const view of views){if(!view.root.isConnected){views.delete(view);continue;}const value=String(index);view.select.replaceChildren(...tracks.map((track,i)=>{const option=el('option',track.title);option.value=String(i);return option;}));view.select.value=index<0?'0':value;view.status.textContent=note.textContent;view.play.textContent=audio.paused?'Play':'Pause';view.play.disabled=!tracks.length;view.prev.disabled=view.next.disabled=!tracks.length;}}
async function play(i){
 if(!bridge()?.ready()||!tracks.length)return;clear();const current=++ticket,who=bridge().owner();index=(i+tracks.length)%tracks.length;title.textContent=tracks[index].title;message('Loading track…');
 try{const descriptor=tracks[index].media;if(!descriptor||descriptor.status!=='ok')throw Error('Track unavailable. Check file access or update the playlist.');let src=descriptor.url;
  if(descriptor.source!=='external'){loading=new AbortController();const blob=await bridge().mediaBlob(descriptor.path,loading.signal);if(current!==ticket||who!==bridge().owner())return;blobURL=URL.createObjectURL(blob);src=blobURL;}
  if(current!==ticket||who!==bridge().owner()||!bridge().ready())return;audio.src=src;dock.hidden=false;await audio.play();message('Playing · '+tracks[index].title);
 }catch(error){if(current===ticket){message(error.message||'Playback unavailable. Press Play to retry.');}}update();
}
function toggle(){if(index<0||!audio.getAttribute('src')){play(index<0?0:index);return;}if(audio.paused)audio.play().catch(()=>message('Press Play in the audio controls.'));else audio.pause();}
stop.addEventListener('click',()=>{clear();index=-1;message('Music stopped.');});audio.addEventListener('ended',()=>{if(index+1<tracks.length)play(index+1);else message('Playlist finished.');});audio.addEventListener('play',update);audio.addEventListener('pause',update);audio.addEventListener('error',()=>message('Audio unavailable or unsupported by this browser.'));
function render(root){const controls=el('div');controls.className='music-controls';const select=el('select');select.setAttribute('aria-label','Playlist track');const prev=el('button','Previous'),playButton=el('button','Play'),next=el('button','Next'),status=el('p');[prev,playButton,next].forEach(button=>button.type='button');controls.append(prev,playButton,next,select);root.append(controls,status);views.add({root,select,prev,play:playButton,next,status});select.addEventListener('change',()=>play(Number(select.value)));prev.addEventListener('click',()=>play(index<0?0:index-1));next.addEventListener('click',()=>play(index+1));playButton.addEventListener('click',toggle);queueMicrotask(update);}
window.dashboardMusic={render};
const mount=document.getElementById('music-mount');if(!mount)return;mount.append(el('h3','Music Player'),el('p','Your playlist · up to 10 tracks. Music continues across Dashboard tabs.'));render(mount);
const rows=el('div'),actions=el('div'),reload=el('button','Refresh audio sources'),add=el('button','Add track'),save=el('button','Save playlist'),addSlot=el('button','Add Music Player to Overview'),feedback=el('p');rows.id='music-playlist-rows';add.id='music-add-track';save.id='music-save';addSlot.id='music-add-slot';[reload,add,save,addSlot].forEach(button=>button.type='button');actions.append(reload,add,save,addSlot);mount.append(rows,actions,feedback);let readers=[];
function row(track={title:'',settings:{source:'external',url:''}}){if(readers.length>=10){feedback.textContent='Maximum 10 tracks.';return;}const box=el('div');box.className='music-track';const name=el('input'),source=el('select'),url=el('input'),remove=el('button','Remove');remove.type='button';name.placeholder='Track title';name.setAttribute('aria-label','Track title');name.maxLength=100;name.value=track.title;url.type='url';url.placeholder='https://example.com/audio.mp3';url.setAttribute('aria-label','Audio URL');url.value=track.settings.url||'';
 const external=el('option','External HTTPS audio');external.value='external';source.append(external);source.setAttribute('aria-label','Audio source');for(const [key,list] of [['upload',library.uploads],['server',library.server_files]])for(const file of list.filter(file=>file.kind==='audio')){const option=el('option',`${key}: ${file.name||file.filename}`);option.value=key+':'+(file.id||file.filename);source.append(option);}
 const cfg=track.settings,selected=cfg.source==='external'?'external':cfg.source+':'+(cfg.file_id||cfg.filename);if(![...source.options].some(o=>o.value===selected)){const option=el('option','Unavailable saved source');option.value=selected;source.append(option);}source.value=selected;
 const show=()=>url.hidden=source.value!=='external';source.addEventListener('change',show);show();
 const read=()=>{const split=source.value.indexOf(':'),kind=split<0?'external':source.value.slice(0,split),value=split<0?'':source.value.slice(split+1);return {title:name.value.trim(),settings:{source:kind,url:kind==='external'?url.value.trim():'',file_id:kind==='upload'?value:'',filename:kind==='server'?value:'',format:'auto',loop:false}};};readers.push(read);remove.addEventListener('click',()=>{readers=readers.filter(r=>r!==read);box.remove();});box.append(name,source,url,remove);rows.append(box);
}
function editor(){rows.replaceChildren();readers=[];tracks.forEach(row);}
async function refresh(){if(!bridge()?.ready())return;const who=bridge().owner();try{const [data,files]=await Promise.all([bridge().slotRequest('music'),bridge().slotRequest('media/library')]);if(!bridge().ready()||who!==bridge().owner())return;owner=who;tracks=data.tracks;library=files;editor();message(tracks.length?'Ready. Press Play.':'Select up to 10 tracks in Media.');}catch(_){feedback.textContent='Could not load playlist.';}}
reload.addEventListener('click',async()=>{if(!bridge()?.ready())return;const who=bridge().owner(),draft=readers.map(read=>read());reload.disabled=true;try{const files=await bridge().slotRequest('media/library');if(!bridge().ready()||who!==bridge().owner())return;library=files;rows.replaceChildren();readers=[];draft.forEach(row);feedback.textContent='Audio sources refreshed.';}catch(_){feedback.textContent='Could not refresh audio sources.';}finally{reload.disabled=false;}});
add.addEventListener('click',()=>row());save.addEventListener('click',async()=>{if(!bridge()?.ready())return;save.disabled=true;try{const who=bridge().owner(),data=await bridge().slotRequest('music',{tracks:readers.map(read=>read())},'PUT');if(!bridge().ready()||who!==bridge().owner())return;clear();index=-1;tracks=data.tracks;editor();message('Playlist saved. Press Play.');feedback.textContent='Playlist saved.';}catch(error){feedback.textContent=error.message||'Playlist could not be saved. Check all sources.';}finally{save.disabled=false;}});
addSlot.addEventListener('click',async()=>{if(!bridge()?.ready())return;addSlot.disabled=true;let created=null;try{created=await bridge().createSlot();await bridge().bind(created.slot,'music-player',{},false);await bridge().setOverview(created.slot,true);feedback.textContent='Music Player added. Open Overview or refresh Slots.';document.dispatchEvent(new Event('music-slot-added'));}catch(_){feedback.textContent=created?'Slot created. Check Slots before retrying.':'Could not add Music Player.';}finally{addSlot.disabled=false;}});
document.addEventListener('dashboard-account-state',event=>{if(event.detail.ready)refresh();else{owner='';clear();index=-1;tracks=[];library={uploads:[],server_files:[]};editor();message('Sign in to use your playlist.');feedback.textContent='';}});if(bridge()?.ready())refresh();
})();
</script>
'''
